import{_ as a,o as p,c as n,a2 as t}from"./chunks/framework.UI9KxY5t.js";const h=JSON.parse('{"title":"红果漫剧锐评","description":"只记录真正看完的红果漫剧，半星评分，点开可看故事节点。","frontmatter":{"title":"红果漫剧锐评","description":"只记录真正看完的红果漫剧，半星评分，点开可看故事节点。","date":"2026-11-17T00:00:00.000Z","category":"浮生清欢","subCategory":"漫剧锐评","tags":["漫剧","红果","影评"],"author":"闲生"},"headers":[],"relativePath":"posts/life/drama/hongguo-drama-reviews.md","filePath":"posts/life/drama/hongguo-drama-reviews.md"}'),r={name:"posts/life/drama/hongguo-drama-reviews.md"};function l(i,s,e,d,o,c){return p(),n("div",null,[...s[0]||(s[0]=[t('<h1 id="红果漫剧锐评" tabindex="-1">红果漫剧锐评 <a class="header-anchor" href="#红果漫剧锐评" aria-label="Permalink to &quot;红果漫剧锐评&quot;">​</a></h1><p>短剧图的是下饭和放松，但看得多了，套路一眼就能望到头。这个页面只做一件事：把真正看完的红果漫剧记下来，给个分数，写几句实话。</p><p>不追新，不凑数，没看完的不写。</p><h2 id="评分标准" tabindex="-1">评分标准 <a class="header-anchor" href="#评分标准" aria-label="Permalink to &quot;评分标准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>评分</th><th>含义</th></tr></thead><tbody><tr><td>5.0</td><td>值得二刷，会主动推荐给别人</td></tr><tr><td>4.5</td><td>差一点满分，有明显亮点</td></tr><tr><td>4.0</td><td>值得一看，整体不错</td></tr><tr><td>3.0</td><td>中规中矩，打发时间可以</td></tr><tr><td>2.0</td><td>槽点较多，只适合边吐槽边看</td></tr><tr><td>1.0</td><td>不推荐，看完只觉得浪费时间</td></tr></tbody></table><p>评分只看三件事：故事有没有讲完、人物的行为有没有动机、爽点是不是靠降智换来的。制作是否精致排在后面，短剧的成本摆在那里，不苛求。</p><h2 id="收录列表" tabindex="-1">收录列表 <a class="header-anchor" href="#收录列表" aria-label="Permalink to &quot;收录列表&quot;">​</a></h2><div class="drama-card"><div class="drama-head"><h3>万妖图录传</h3><span class="drama-genre">玄幻 · 志怪 · 穿越</span></div><div class="drama-rating"><span class="stars" style="--pct:100%;">★★★★★</span><span class="drama-score">5.0</span></div><p class="drama-intro">现代少女姜月初魂穿盛唐，成了罪臣之女，得到上古至宝《万妖图录》：以妖血为墨、绘妖入谱，便能夺取对方神通。从虎山神到白猿公，她一路斩妖升级，也一步步揭开长安繁华之下的仙神棋局。</p><p class="drama-path">境界：鸣骨 → 点墨 → 种莲 → 观山 → 燃灯 → 登楼 → 执棋 → 画境 → 落墨 → 流丹（当前）→ 游虚海 → 万象天 → 太上京</p><details><summary>故事节点</summary><ol class="timeline"><li><span class="phase">第 1–2 季 · 长安觉醒</span><strong>鸣骨境</strong><p>穿越成罪臣之女，父亲待斩；激活万妖图录，初斩虎山神得霸道刀法。入镇魔司、赴玉门关，月圆夜强破鸣骨境，凭一己之力斩杀自号「平天真君」的白猿公，又硬撼白蛟龙夺来控水之力。白猿公苦苦等待的「归妖」，正是姜月初随手斩杀的那只小虎妖——父子线从这里埋下，成为后续最意难平的一笔。</p></li><li><span class="phase">第 3–5 季 · 长安权谋</span><strong>点墨境</strong><p>升任银袍巡察使，识破九尾狐混入镇魔司；察觉朝堂豢养妖魔、皇室与佛门残余勾结。为补全被撕裂的图录深入蛮荒秘境，收青鸾、黑山熊君、鲲鹏后裔，解锁「万妖共鸣」，并窥见仙佛献祭众生、抽取灵气飞升的上古真相。</p></li><li><span class="phase">第 6–7 季 · 身世揭晓</span><strong>种莲 → 燃灯</strong><p>青鸟龙纹佩坐实养父罪名，天眼神术为其洗冤，姜月初真实身份揭晓——她竟是失踪多年的昭月长公主，同时隐藏人妖混血之秘。远征西荒组建万妖联军，正面对决黑化的生父太上皇。第七季结尾，白玉楼燃尽神魂独战两尊妖圣，殉道前留下遗言「请替我给隔壁阿沅送碗热汤面」，以燃灯境陨落。</p></li><li><span class="phase">第 8–10 季 · 登楼破局</span><strong>登楼境</strong><p>踏入归墟解封禁忌，洗龙池承接真龙道统，打上五仙山揭穿香火道伪仙，连诛千羽、赤血诸妖皇，硬撼执棋级仙君对手。圆满时顿悟自己只是画境大能掌中的棋子，誓要斩碎樊笼。</p></li><li><span class="phase">第 11–12 季 · 云梦宫大战</span><strong>执棋 → 画境</strong><p>白象妖皇携《星宫图录》现世，云梦宫十万妖兵直逼长安（第 12 季高潮）。姜月初主动引开大军，把战火带离百姓；执棋十六子圆满，借星宫图录踏入画境，随后杀入天庭，获封正九品御马仙司掌印。</p></li><li><span class="phase">第 13–14 季 · 天庭新篇</span><strong>落墨 → 流丹初境</strong><p>登临天庭即新手，对手从能正面击败的妖魔变成底蕴深厚的仙神教派。她设计诱杀城隍坐骑红二郎，再以天界律法条文应对巡查使审问，完成从「凡界战神」到「天庭执棋者」的转身。</p></li></ol></details></div><div class="drama-card"><div class="drama-head"><h3>凡人百世书</h3><span class="drama-genre">仙侠 · 轮回 · 复仇</span></div><div class="drama-rating"><span class="stars" style="--pct:100%;">★★★★★</span><span class="drama-score">5.0</span></div><p class="drama-intro">资质平庸的陈默身负灭门之仇，濒死时觉醒百世轮回系统：每死一次，意识不灭、资质叠加。十九世走下来，他把报仇这件事，一步步走成了守城、改命，最终连向仙界真相。</p><p class="drama-path">六条主线：陈平安 · 关山月 · 金霞宗 · 桃花坞/丫丫 · 神衍观 · 平乱军</p><details><summary>故事节点</summary><ol class="timeline"><li><span class="phase">第 1–3 世 · 复仇</span><strong>从灭门到初步收网</strong><p>第一世陈默灭门复仇，横死时百世书开启；第二世林默潜入紫衣门追查真相；第三世林惊蛰灭仇家，完成初步复仇。</p></li><li><span class="phase">第 4 世 · 转折</span><strong>边关名将与失踪的弟弟</strong><p>陈破虏成为边关名将，守国而死。弟弟陈平安在边关大战后神秘失踪，母亲梦见「仙人韩仙翁将他接走」——这条线把复仇故事第一次推向「人之外」。</p></li><li><span class="phase">第 5–7 世 · 由凡入仙</span><strong>悬壶、出海、踏仙途</strong><p>叶玄被囚皇城却悬壶济世，与关山月结下巨大因果；独孤城自白云秘境出海寻仙，玄龟载着关山月抵达灵起大陆；张玄真踏入修仙界。</p></li><li><span class="phase">第 8–9 世 · 立宗</span><strong>为宗献身，创建金霞宗</strong><p>赵凌云在神魔战场为宗献身；陈临以金霞祖师身份创建金霞宗，宗门壮大、庇护苍国。这是主角第一次留下可继承的势力资产，后世能回收前世的资源、人脉与影响力。</p></li><li><span class="phase">第 10–12 世 · 守边与解执念</span><strong>铁手人屠、桃花坞、北域大战</strong><p>雷铸以「铁手人屠」之名镇守边关；杨玄镇守桃花坞并收下丫丫，发掘出她惊人的阵法天赋；郑耀祖在北域大战中解开横跨七世的关山月执念。</p></li><li><span class="phase">第 13–15 世 · 命数</span><strong>神衍观三证</strong><p>刘半仙证「知命」，陈念证「信命」，不尘入神衍观证「逆天改命」，留下神衍一脉改变命运的传承，后世小辈继续成长。</p></li><li><span class="phase">第 16–18 世 · 战争</span><strong>沙漠王城与平乱军</strong><p>凌天以耀穹星少星主的身份成就羽化境，显城战场；王小二羽化三重，在邪魔域救下危局；萧玄建立平乱军，统一百座边境修仙大城，构筑玄黄防线。</p></li><li><span class="phase">第 19 世 · 进行中</span><strong>飞鹤门认出弟弟</strong><p>陈默重返大战，飞鹤门开启。他在门中看到一幅仙尊画像，认出正是当年被仙人接走的陈平安；而飞鹤门的典故，是师徒「仙人下凡、追捕上界逃犯」。凡人百世的轮回，到这里正式与仙界接上了线。</p></li></ol></details></div><div class="drama-card"><div class="drama-head"><h3>聚宝仙盆之杂灵根才是真BOSS</h3><span class="drama-genre">仙侠 · 凡人流 · 逆袭</span></div><div class="drama-rating"><span class="stars" style="--pct:90%;">★★★★★</span><span class="drama-score">4.5</span></div><p class="drama-intro">杂役弟子贺平生觉醒五行杂灵根，被太虚门贬去挑水，却意外捡到一只破陶盆——聚宝仙盆，能复制、翻倍、强化丹药功法。别人眼里的废灵根，他一路从凡界打到神界，最后才发现：杂灵根从来不是废体。</p><p class="drama-path">四幕：凡界 → 灵界 → 仙界 → 神界（第 16 季进行中）</p><details><summary>故事节点</summary><ol class="timeline"><li><span class="phase">第 1 季 · 凡界篇</span><strong>太虚门杂役，捡到破盆</strong><p>贺平生出身凡界，觉醒五行杂灵根，被贬为杂役，受尽克扣与嘲讽。挑水时得到破旧陶盆，竟是可复制、翻倍、强化丹药功法法器的聚宝仙盆。太虚老祖察觉他灵根异常，布下夺舍杀局，失败后寿元将尽，转而托付宗门传承；随后御兽仙宗入侵，太虚门覆灭，他借传送阵离开凡界。</p></li><li><span class="phase">第 2 季 · 凡界篇</span><strong>逃亡与秘境</strong><p>踏入更广阔的修真世界，闯秘境、遇背叛、救下乔慧珠，逐步甩掉「杂役废物」的标签。九国大比前后，他因仙盆崭露头角，也开始被强权势力盯上。</p></li><li><span class="phase">第 3–4 季 · 凡界篇</span><strong>九国大比与念圣山阴谋</strong><p>为救治乔慧珠深入五龙沟秘境，在九国大比中接连破局；齐国囚禁太虚门旧人，他孤身入局拆解阴谋。随后潜入念圣山，发现圣主长期窃取修士气运延寿，联手正道斩反派、夺本源，却在修复飞升通道时因空间裂变重伤坠入灵界。</p></li><li><span class="phase">第 5–6 季 · 灵界篇</span><strong>坠界者重新起步</strong><p>坠入万族共生的灵界后，他并没有重生，而是从零再来：闯秘境、收真火真雷、周旋各族势力，一点点建立自己的根基。</p></li><li><span class="phase">第 7–8 季 · 灵界篇</span><strong>覆灭风族，人族共主</strong><p>炼丹收火、统御人族、覆灭风族，逆袭线在灵界集中兑现；云台试炼中王敦回归相助，兄弟并肩破关。季末他直面六重紫红劫雷，飞升生死悬于一线。此后收束人族、风族与旧敌线，从逃亡者长成灵界一方霸主。</p></li><li><span class="phase">第 9–11 季 · 仙界篇</span><strong>入局仙界，一魂双身</strong><p>杀入仙界，对手升级为仙神教派、古老道统与佛门势力。第十一季抛出关键反转：温不晚与乔慧珠并非情敌或闺蜜，而是一魂双身。</p></li><li><span class="phase">第 12 季 · 仙界篇</span><strong>金羽夺魁，生死线加身</strong><p>得魔道传承，在金羽之会顶名夺魁，一枪斩落天昴仙王。随后卷入佛门与玄门之争，闯入天佛大会，被种下生死线，遭大罗金仙围杀，重伤遁入紫薇天。</p></li><li><span class="phase">第 13 季 · 仙界篇</span><strong>玄魔天墟数十万年</strong><p>坠入玄魔天墟，内外时间悬殊，他在墟中修炼数十万年，斩道君、逼近混元。本季重点是与乔慧珠重逢，以及温不晚的牺牲与复活。至此主线真相浮出：杂灵根并非废体，而是能承载业力、打破上古骗局的关键；聚宝仙盆也与上古天道轮回盘同源。</p></li><li><span class="phase">第 14–15 季 · 神界篇</span><strong>双魂归一的来处</strong><p>乔慧珠前世为浮屠菩萨转世，后成造化女帝；其师尊浮雪仙子改名凌波仙子，背后牵涉长生帝与玄门三十一位道君。贺平生为守护乔慧珠，对抗长生天等势力，从仙界一路逼向神界。</p></li><li><span class="phase">第 16 季 · 神界篇</span><strong>隐姓埋名，家族受胁</strong><p>闯入神界才发现这里弱肉强食、神格如命。他屡遭追杀、家族受胁，只能易容隐名入秘境冒险，绝境中一次次翻盘，同时为家族开拓新行业、经营势力。始终有个「某人」在暗中提点——是盟友、幕后棋手，还是更高层布局的一部分，仍是悬念。</p></li></ol></details></div><div class="drama-card"><div class="drama-head"><h3>剑神归来：我和驴子的十万年</h3><span class="drama-genre">仙侠 · 系统 · 搞笑</span></div><div class="drama-rating"><span class="stars" style="--pct:80%;">★★★★★</span><span class="drama-score">4.0</span></div><p class="drama-intro">陆川被坑货驴系统阿福困在黑暗空间练剑十万年，出关已成老头。剑道无双却总闪腰，只能带着一头不靠谱的驴闯修真界。</p><details><summary>故事节点</summary><ol class="timeline"><li><span class="phase">开端</span><strong>被驴坑了十万年</strong><p>陆川被系统阿福困在黑暗空间，日复一日练剑。外界只过去一瞬，他却老了十万年。</p></li><li><span class="phase">出关</span><strong>剑道无双，身体报废</strong><p>他握着举世无双的剑道实力，躯体却严重老化，出手前常常先闪了腰。</p></li><li><span class="phase">闯荡</span><strong>秘境与魔域</strong><p>他卷入秘境厮杀，击溃魔域百万大军，闯入青铜神殿窥探大帝秘辛。</p></li><li><span class="phase">远行</span><strong>星空寻路</strong><p>为寻五行本源与回家之路，他带着阿福、四魔和一群帝子小弟闯荡星空，硬撼虚主。</p></li></ol></details></div><div class="drama-card"><div class="drama-head"><h3>我都元婴期了，你跟我说开学</h3><span class="drama-genre">都市 · 修真 · 校园</span></div><div class="drama-rating"><span class="stars" style="--pct:80%;">★★★★★</span><span class="drama-score">4.0</span></div><p class="drama-intro">元婴修士宁尘遭袭重伤，从修真界跌回现代，时间只过了一个暑假，还得去青州大学报到。</p><details><summary>故事节点</summary><ol class="timeline"><li><span class="phase">开端</span><strong>修真界遭袭</strong><p>宁尘在修真界被人偷袭，身负重伤，只能仓促退回现代。</p></li><li><span class="phase">落差</span><strong>暑假还没结束</strong><p>他苦修两千年成就元婴，回到地球才发现时间只流逝了一个暑假。</p></li><li><span class="phase">入学</span><strong>青州大学报到</strong><p>他被迫入学，借住在乔姨家，与傲娇少女许舒颜同住，开始伪装普通学生。</p></li><li><span class="phase">双线</span><strong>上课与修元神</strong><p>白天应付校园日常，暗地寻找修复元神的资源，顺手化解校园和市井里的麻烦。</p></li></ol></details></div><h2 id="关于这个页面" tabindex="-1">关于这个页面 <a class="header-anchor" href="#关于这个页面" aria-label="Permalink to &quot;关于这个页面&quot;">​</a></h2><p>漫剧和短剧的节奏很快，看完容易忘。记下来不是为了给谁看，而是过段时间回头翻，能想起当时为什么愿意一集集点下去。</p><p>如果某部剧的评分和你的观感差得多，那很正常，口味本来就没有标准答案。</p>',15)])])}const m=a(r,[["render",l]]);export{h as __pageData,m as default};
